<?php

namespace Modules\Finance\Services;
use Illuminate\Support\Facades\DB;use Modules\Core\Models\User;use Modules\Finance\Models\AccountMapping;use Modules\Finance\Models\Journal;use RuntimeException;
class GlPostingService{public function __construct(private JournalService$journals){}public function postEvent(int$c,string$event,string$type,int$id,float$amount,string$period,User$user,?string$description=null,?string$journalDate=null):array{if($amount<=0)throw new RuntimeException("Jurnal AUTO [{$event}] memerlukan amount > 0.");$key=hash('sha256',implode('|',[$c,$event,$type,$id]));return DB::transaction(function()use($c,$event,$type,$id,$amount,$period,$user,$description,$journalDate,$key){DB::table('companies')->where('id',$c)->lockForUpdate()->first();$existing=Journal::withoutGlobalScopes()->where('posting_key',$key)->first();if($existing){if(abs((float)$existing->total_debit-$amount)>0.0001)throw new RuntimeException('Idempotency conflict: source jurnal sama memiliki amount berbeda.');return['journal'=>$existing,'created'=>false];}$m=AccountMapping::withoutGlobalScopes()->where('company_id',$c)->where('event',$event)->first();if(!$m)throw new RuntimeException("BR-101: account mapping untuk event [{$event}] belum diisi.");if($m->debit_account_id===$m->credit_account_id)throw new RuntimeException('Debit dan credit mapping tidak boleh akun yang sama.');if(DB::table('chart_of_accounts')->where('company_id',$c)->whereIn('id',[$m->debit_account_id,$m->credit_account_id])->count()!==2)throw new RuntimeException('Account mapping menggunakan COA dari company lain.');$j=$this->journals->post($c,['period'=>$period,'journal_date'=>$journalDate,'source'=>'AUTO','event'=>$event,'source_document_type'=>$type,'source_document_id'=>$id,'posting_key'=>$key,'description'=>$description??$event],[['coa_id'=>$m->debit_account_id,'debit'=>$amount],['coa_id'=>$m->credit_account_id,'credit'=>$amount]],$user);return['journal'=>$j,'created'=>true];});}}
